import{_ as t,c as s,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易圖通變卷五","description":"易圖通變 - 易圖通變卷五","frontmatter":{"title":"易圖通變卷五","description":"易圖通變 - 易圖通變卷五"},"headers":[],"relativePath":"classics/yitu-tongbian/006.md","filePath":"classics/yitu-tongbian/006.md"}'),r={name:"classics/yitu-tongbian/006.md"};function l(o,a,c,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易圖通變卷五",tabindex:"-1"},[i("易圖通變卷五 "),e("a",{class:"header-anchor",href:"#易圖通變卷五","aria-label":"Permalink to “易圖通變卷五”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"宋雷思齊撰",-1),e("p",null,"古聖人之王天下，創始公至理以惠啟千萬世者，豈易易然率己見以自擅製作哉？此有天授，斷可識矣。故河之出圖，伏羲因之以則而畫八卦；洛之出書，大禹因之以則而敘九疇。孔子於大傳敘天生神物，聖人則之，而兼及圖書，而謂其兼則之也。子不語怪力亂神，豈無所見於真實，而自樂為虛誕以愚欺天下後世哉？自稱庖羲氏之王天下，仰則觀象於天，俯則觀法於地，觀鳥獸之文與地之宜，近取諸身，遠取諸物，始作八卦，以通神明之德，以類萬物之情，是豈先聖後聖各以私意淺識得措乎其間哉？易之廣大配天地，變通配四時，陰陽之義配日月。其為書廣大悉備，與乾坤相為終始而無弊，非有天授，能為是乎？此孔子有見於圖書之出，特謂「則之」而已，無它說也。況圖之自見於成、康，顧命陳之東序之後，無所復聞，孔子固己自悲其不出，而有己夫之嘆。漢儒之始孔安國，乃由書傳於河圖東序之下，謂伏羲王天下，龍馬負圖出河，遂則其文謂之河圖。於「天乃錫禹洪範九疇」之下，謂天錫禹洛書，神龜負文而出，列於背，有數從一至九，禹因而第之，以成九類，類即疇也。是二說自分載於洪範、顧命各篇本語之下，亦未之有它說也。至鄭康成始引春秋緯合注大傳之圖、書雲：河以通乾出天苞，洛以流坤吐地符。河圖龍發，洛書龜感。河圖有九篇，洛書有六篇，已是詭說之開端，然仍引安國之注，以為河圖八卦是也，洛書九疇是也。其後王輔嗣、韓康伯於此並無所註釋，惟孔穎達易疏雖全篇寫鄭注，亦謂輔嗣之義未知何從，是必未以鄭注為然也。及其疏書之洪範，乃又引繫辭雲：「河出圖，洛出書，聖人則之。」九類各有文字，即是書也。而云「天乃錫禹」，知此天與禹者即洛書。就引漢書五行志劉歆以為伏羲系天而王，河出圖，則而畫之，八卦是也。禹治洪水，錫洛書，法而陳之，洪範是也。河圖、洛書相為經緯，八卦、九章相為表裡。 附說：先達共為此說。龜負洛書，經無是事。中候及諸緯多說黃帝、堯、舜、禹、湯、文、武受圖書之事，皆雲龍負圖，龜負書。緯候之書，不知誰作，通人討核，謂偽起哀、平，雖復前漢之末始有此書，已前學者必相傳此說，故孔以為九類是神龜負文而出，列於其背，有數從一至九，禹見其文，因而第之，以成九類法也。言禹第之者，以天神言語必當簡要，不應曲有次第，丁寧如此，故以為語第之也。 全文 其疏顧命之「河圖東序」及疏記之「河出馬圖」，詳略雖小有殊同，指意大校若此。是則所謂河圖為八卦，所謂洛書為九疇，並無改議也。",-1),e("p",null,"由漢而唐，易經行世，凡經傳疏釋之外，未有及於圖書之文刊列經首者。迨故宋之初，陳摶圖南始創意推明象數，自謂因玩索孔子三陳九卦之義，得其遠旨，新有書述，特稱龍圖離合變通圖，餘二十是全用大傳「天一地二至天五地十，五十有五」之數，雜以納甲，貫穿易理。內一圖謂形九宮，附一圖謂形洛書者，則盡去其五生數，祇起地六至地十，自釋十為用，十為成形，故洪範「陳五行之用」數語而已。及終其書，再出兩圖，其一形九宮者，元無改異，標為河圖；其一不過盡置，列大傳五十有五之數於四方及中，而自標異，謂為洛書，並無傳例言說，特移二七於南，四九於西，莫可知其何所祖法而作，而標以此名，大抵因如前說洪範五行之二火四金，太玄準易因之為二南四西而然。然其流傳未遠，知者亦鮮。自圖南五傳而至劉牧長民，乃增至五十五圖，名以鉤隱。師友自相推許，更為唱述，各於易間有註釋，曰卦德論，曰室中語，曰記師說，曰指歸，曰精微，曰通神，亦總謂周易新注。每欲自神其事，及跡而究之，未見其真能有所神奇也。時則有李覯泰伯著六論以駮其非是，至謂懼其詿誤學子，壞隳世教，而刪其圖之復重，存之者三焉：河圖也，洛書也，八卦也。夫長民之多為圖畫，固未知其是，而泰伯亦元未識此圖之三，本之則一爾。河圖本列八卦，而數五十有五也。及長民輩始破洛書古說，謂非只是洪範，必別有書出於羲之上世，羲乃得而並則之，以作易也。泰伯之見，則又與之同。此愚又莫能知何為其然也。蓋嘗夷考大傳，此章自有「法象天地，變通四時，縣象日月」，而又有及於蓍龜，故因謂之「天生神物，聖人則之」者，正謂蓍也。易惟蓍是用，所謂「蓍之德員而神幽，贊於神明而生蓍」，易豈有龜事哉？因其均可以佔，故牽聯及龜爾。以上文謂「法象天地，變通四時」，故申之曰「天地變化，聖人效之」。上文謂「縣象日月」，故申之曰「天垂象，聖人象之」。至於「天生神物」，乃申謂之如河出圖，洛出書，聖人亦得以則之也。蓋由河之出圖，羲前既得以則而畫卦，因及於洛之出書，禹後復得以則而敘疇爾，又豈害於比類而互言之哉？豈嘗直欲以圖書之數之義之條貫比而同之哉？豈嘗直謂圖書並出於一時哉？且不惟漢儒引洪範以為洛書，雖圖南之初，謂形洛書者，亦不過謂十為用，十為成形，故洪範陳五行之用也者，是明指洛書為洪範矣。不知長民輩不本其初，故倍其師傳，而謂洛書非出於禹之時，益使後之人迷亂而失所據依，何也？又不謂孔子之謂聖人之則之也，非特八疇分佈四正四維，五行置於坎一，五事置於坤二，五紀置於巽四，五福置於離九，一以九疇之次敘陳列於河圖之卦次。夫九疇謂禹次第之者，直自初一、次二、次三四，而以次用之也。今隨河圖十五縱橫而置之，則成亂次矣，未暇一一辨詰。且以初一之五行言之，既謂五行，自當分配五方，何得以五者限萃一方，不以推行，惡得謂五行哉？以至謂「火金易位」，與河圖不同，其顛倒迷繆不可訓知若此。其後楊次公自著洞極經，託名於關子明，其敘本萹稱：「子曰：河圖之本，七前六後，八左九右，聖人觀之以畫八卦。是故全七之三以為離，奇以為巽；全八之三以為震，奇以為艮；全六之三以為坎，奇以為乾；全九之三以為兌，奇以為坤。正者全其位，隅者盡其畫。而謂四象生八卦，此謬之尤者。乾坤相索而生六子，今為男女者，反能生父母之卦邪？況泛言二七為火，四九為金，猶可謾所未識者，今至明言離九為七，兌七為九，是河圖一可變置矣，而可乎？又謂洛書之文，五處其中，九前一後，三左七右，四前左，二前右，八後左六後右，後世稽之以為三象，因而九變之以二十七象。」今案其說，惟「五處其中」一語於洛書不悖，餘悉河圖之數。而河圖之數乃因洛書以五處中，而盡失其所以為五之理爾。書之九疇，以皇極之五處中，固無別用，是可以定去羲之時將幾世幾年，雖祇去禹之世，固已千數百年矣。其稱書之出洛，以比羲之圖之出河，於理惡乎而不可？長民故為此說，是且並孔子之大傳不之信邪？考圖南之為龍圖，雖自謂得於孔子三陳九卦之旨而作，然其序曰：「龍圖者，天散而示之，羲合而用之，孔默而形之。」且明稱始圖之未合，惟五十五數，則是謂大傳天數二十有五，地數三十合而言之，不知何以於其末改標之以為洛書，殆其始誤也，長民輩乃承誤而益增其誤，遂真以為洛書，而有五十五圖以實其誤。以至泰伯已後，悉以圖南之標異之五十五數為真洛書也。不思圖南標洛書之始，偶謂用十。夫洛書所敘九疇，其十數當何從而起哉？意豈謂大傳之河圖既可出而示世，則洛書亦可以並出示之，因假大傳五十五數託為書之九疇乎？九疇所言，皆用縱比而同之謂五十五數，其用又安在哉？此不可之大者也。故嘗因長民之事討其原。圖南之後，种放、許堅、李溉未及見其它有著述。若其所親授之師，如範諤昌所著大易源流，其稱「龍馬負圖出河，羲皇窮天人之際，重定五行生成之數，定地上八卦之體。」故老子自西周傳授孔子造易之原，天一正北，地二正南，天三正東，地四正西，天五正中央，地六配子，天七配午，地八配卯，天九配酉，地十配中，寄於末，乃天地之數五十有五矣。因考其既以圖之前五數置於北南東西之正及中，復以後五數配子午卯酉及中，何也？夫子午卯酉非四方之正邪？地十配中，雲寄於末，夫中抑有末邪？諦詳所置之數，正令圖所傳有四方而無四維之數者。是諤昌巳元不識圖南所以標異，特因太玄準易，取於洪範一水二火三木四金五土而然，鑿空無故造端老子，增立怪論，以實圖南易置二七四九之位爾。然猶未嘗以九疇分配九宮也。究核諤昌之取用，不過循納甲之緒餘，及五子歸庚之殊向。又謂天上八卦坎離對中之外，移置乾兌坤於東，艮震巽於西，不謂五行之說多起於易後，而反引五行以為定卦之原，此又其敢於創異之大端也。是宜長民不獨增以五十五圖，又因諤昌坎離震兌四正之外，而以四成數同於四方，謂坎六退本卦三數，以餘三數三畫為乾。離七退本卦三數，以餘四數四畫為巽。震八數，退本卦三數，以餘五數五畫為艮；兌九數，退本卦三數，以餘六數六畫為坤。皆以數為畫，標為河圖，是不揣本而齊末。夫八卦各三畫，以剛柔生爻，未聞本卦只用三畫，而以其餘畫之多，反分為別卦也。所陳之數抑配偶然，且以坎離震兌為四象，則尤非也。象本在未成卦之先，故曰「四象生八卦」也。又云：洛書之九疇，本河圖自然之數，虛皇極於中而以位也。至河圖之有天五，乃兼地十以為十五，其五乃四分於成數之內而合於十，豈嘗有五虛點而實置於圖之中位哉？圖之傅誤正由此。五次公之假設此妄例，特以蓋其所祖者，乃揚子云三方九州而二十七部私以為書耳。於斯二者，固已真易置圖書矣。而朱元晦、蔡季通反祖之，信以為關子明作也，不計子明之易傳精詣，豈此摹擬者比？乃循此膚臆之見，因扶其說，亦謂河圖七前六後八左九右，洛書之文九前一後三左七右，四前左二前右，八後左六後右。謂大傳既陳五十有五數，洪範又謂「天乃錫禹洪範九疇」，而九宮之數戴九履一，左三右七，二四為肩，六八為足，正龜背之象。劉牧意見以九為河圖，十為洛書，託言出於希夷，與諸儒舊說不合。又引大傳以為二者皆出於伏羲之世，其易置圖書，並無明驗。其朱蔡之指斥又如此。而直以「圖南」始標誤之洛書為河圖，而以其初正指河圖反以為洛書，則朱蔡實自誤，而反罪長民之先誤，專己自是，張其辯說，不克自反，一至於此。惟程泰之易原時能理到。至鄭東卿輩尋跡依傍，一意誕謾，廣增圖說，皆非實指，徒使後之人失其真是，信其所不當信，疑其所不當疑，並與本來宗旨樊然擾亂，是其所非而非其所是。跡究其始，不過由「圖南用十」之一語立一圖之誤。至於為此紛紛，始猶借河圖以相因依，而為洛書之說，久則舍圖取書，又久乃遂以書為圖，荒然莫知河圖為何物，所以有圖者實為何事。執其五十五數以為圖，不知其五十五數其始特以誤及洛書，今反執之為圖。是圖既非圖，其謂書以為圖者，書益非其書者矣。徒自言人人殊，使學者亡羊多岐，求馬唐肆，紛如聚訟，吾誰適從？不啻三百年於此。故推原致誤之由，疏列群疑之妄，直以河圖本數討正之，庶幾學者見之了焉，會心自斷，知「圖南」之謂其由三陳九卦而得者，類於謾；陰陽家襲於以一六八白取以為起例者，流於末。若乾鑿度以謂太一取其數以行四正四維皆合十五者，鑿於緯之拘贅，亦不盡然。然從昔儒先莫不斷斷然謂非人所能偽作者。今以餘自本觀之，直謂不必它求，特以說卦「帝出乎震」一章，環中往復參究之，以天一至地四、地六至天九求其實體，天五與地十明其虛用，則參伍以變，參天兩地，錯綜倚數，莫不左右逢原，一皆脗合乎孔子系易之初旨，是之謂眾言淆亂折諸聖，則明河之出圖，通古不妄，足以見易矣。因洞悉洛之出書，九疇之外豈復有圖有數之妄作者，誠古今之一大快事也。易圖通變卷五。",-1)])])}const f=t(r,[["render",l]]);export{_ as __pageData,f as default};
